<script>
document.querySelectorAll('[data-confirm]').forEach(f=>f.addEventListener('submit',e=>{if(!confirm(f.dataset.confirm))e.preventDefault()}));
document.querySelectorAll('[data-editor]').forEach(editor=>{const target=document.getElementById(editor.dataset.editor);editor.innerHTML=target.value;const sync=()=>target.value=editor.innerHTML;editor.addEventListener('input',sync);editor.closest('.editor-wrap').querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>{document.execCommand(b.dataset.command,false,b.dataset.value||null);editor.focus();sync()}))});
</script></body></html>
